=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs.v
// AXI4-Lite subordinate with four 32-bit read/write registers.
// Implements microarchitecture.md: holding registers for AW and W,
// READY computed from state only, one outstanding transaction per direction,
// SLVERR for unmapped (misaligned) addresses, 1-cycle response latency.
`default_nettype none

module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;
    localparam       NSTRB       = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    // Write side: the two held flags plus bvalid.
    reg                  aw_held_q;
    reg                  w_held_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    // Read side: rvalid and its payload.
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    // Register file: four separate flops, no memory inference.
    reg [DATA_WIDTH-1:0] reg0_q;
    reg [DATA_WIDTH-1:0] reg1_q;
    reg [DATA_WIDTH-1:0] reg2_q;
    reg [DATA_WIDTH-1:0] reg3_q;
    // Holding registers: datapath, not reset (microarchitecture section 2),
    // only used while the matching held flag is set.
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [DATA_WIDTH-1:0] w_data_q;
    reg [NSTRB-1:0]      w_strb_q;

    // ------------------------------------------------------------------
    // Handshakes: READY is a function of state only
    // ------------------------------------------------------------------
    wire aw_ready = !aw_held_q && !bvalid_q;
    wire w_ready  = !w_held_q  && !bvalid_q;
    wire ar_ready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && aw_ready;
    wire w_hs  = s_axil_wvalid  && w_ready;
    wire ar_hs = s_axil_arvalid && ar_ready;
    wire b_hs  = bvalid_q && s_axil_bready;
    wire r_hs  = rvalid_q && s_axil_rready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);
    wire aw_load  = aw_hs && !do_write;
    wire w_load   = w_hs  && !do_write;

    // Held copy when one exists, else the live bus.
    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    wire [NSTRB-1:0]      wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;
    wire [1:0]            wr_idx  = wr_addr[3:2];
    wire [1:0]            rd_idx  = s_axil_araddr[3:2];

    // ------------------------------------------------------------------
    // Address decode: mapped when word aligned and addr >> 4 == 0
    // ------------------------------------------------------------------
    wire wr_hi_zero;
    wire rd_hi_zero;
    generate
        if (ADDR_WIDTH > 4) begin : g_addr_wide
            assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
            assign rd_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
        end else begin : g_addr_narrow
            assign wr_hi_zero = 1'b1;
            assign rd_hi_zero = 1'b1;
        end
    endgenerate

    wire wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;

    // ------------------------------------------------------------------
    // Write merge: merge(old, data, strb)
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] wr_old;
    always @* begin
        case (wr_idx)
            2'd0:    wr_old = reg0_q;
            2'd1:    wr_old = reg1_q;
            2'd2:    wr_old = reg2_q;
            default: wr_old = reg3_q;
        endcase
    end

    wire [DATA_WIDTH-1:0] wr_mask;
    genvar gi;
    generate
        for (gi = 0; gi < NSTRB; gi = gi + 1) begin : g_wr_mask
            assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] wr_merged = (wr_old & ~wr_mask) | (wr_data & wr_mask);

    // ------------------------------------------------------------------
    // Read select
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_value;
    always @* begin
        case (rd_idx)
            2'd0:    rd_value = reg0_q;
            2'd1:    rd_value = reg1_q;
            2'd2:    rd_value = reg2_q;
            default: rd_value = reg3_q;
        endcase
    end

    // ------------------------------------------------------------------
    // Next state
    // ------------------------------------------------------------------
    reg                  aw_held_d;
    reg                  w_held_d;
    reg                  bvalid_d;
    reg [1:0]            bresp_d;
    reg                  rvalid_d;
    reg [1:0]            rresp_d;
    reg [DATA_WIDTH-1:0] rdata_d;
    reg [DATA_WIDTH-1:0] reg0_d;
    reg [DATA_WIDTH-1:0] reg1_d;
    reg [DATA_WIDTH-1:0] reg2_d;
    reg [DATA_WIDTH-1:0] reg3_d;

    always @* begin
        aw_held_d = aw_held_q;
        w_held_d  = w_held_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rresp_d   = rresp_q;
        rdata_d   = rdata_q;
        reg0_d    = reg0_q;
        reg1_d    = reg1_q;
        reg2_d    = reg2_q;
        reg3_d    = reg3_q;

        // Write response channel
        if (b_hs) begin
            bvalid_d = 1'b0;
        end
        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            if (wr_mapped) begin
                bresp_d = RESP_OKAY;
                case (wr_idx)
                    2'd0:    reg0_d = wr_merged;
                    2'd1:    reg1_d = wr_merged;
                    2'd2:    reg2_d = wr_merged;
                    default: reg3_d = wr_merged;
                endcase
            end else begin
                bresp_d = RESP_SLVERR;
            end
        end else begin
            if (aw_hs) begin
                aw_held_d = 1'b1;
            end
            if (w_hs) begin
                w_held_d = 1'b1;
            end
        end

        // Read channel
        if (r_hs) begin
            rvalid_d = 1'b0;
        end
        if (ar_hs) begin
            rvalid_d = 1'b1;
            if (rd_mapped) begin
                rdata_d = rd_value;
                rresp_d = RESP_OKAY;
            end else begin
                rdata_d = {DATA_WIDTH{1'b0}};
                rresp_d = RESP_SLVERR;
            end
        end
    end

    // ------------------------------------------------------------------
    // State registers (synchronous, active-low reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            w_held_q  <= 1'b0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= {DATA_WIDTH{1'b0}};
            reg0_q    <= {DATA_WIDTH{1'b0}};
            reg1_q    <= {DATA_WIDTH{1'b0}};
            reg2_q    <= {DATA_WIDTH{1'b0}};
            reg3_q    <= {DATA_WIDTH{1'b0}};
        end else begin
            aw_held_q <= aw_held_d;
            w_held_q  <= w_held_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rresp_q   <= rresp_d;
            rdata_q   <= rdata_d;
            reg0_q    <= reg0_d;
            reg1_q    <= reg1_d;
            reg2_q    <= reg2_d;
            reg3_q    <= reg3_d;
        end
    end

    // Holding registers (load enable only, no reset)
    always @(posedge aclk) begin
        if (aw_load) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_load) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = aw_ready;
    assign s_axil_wready  = w_ready;
    assign s_axil_arready = ar_ready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 7).
    // Not proven by this deliverable: no SymbiYosys job accompanies it.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk)
        f_past_valid <= 1'b1;

    // Environment: reset on the first cycle; VALIDs low while in reset.
    always @(*) begin
        if (!f_past_valid)
            assume (!aresetn);
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    // Manager holds VALID and payload until READY.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume (s_axil_awvalid);
                assume (s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume (s_axil_wvalid);
                assume (s_axil_wdata == $past(s_axil_wdata));
                assume (s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume (s_axil_arvalid);
                assume (s_axil_araddr == $past(s_axil_araddr));
            end
        end
    end

    // Responses are low after reset.
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert (!s_axil_bvalid);
            assert (!s_axil_rvalid);
            assert (!aw_held_q);
            assert (!w_held_q);
        end
    end

    // Responses hold until taken and follow only accepted requests.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn)) begin
            if ($past(s_axil_bvalid && !s_axil_bready)) begin
                assert (s_axil_bvalid);
                assert (s_axil_bresp == $past(s_axil_bresp));
            end
            if ($past(s_axil_rvalid && !s_axil_rready)) begin
                assert (s_axil_rvalid);
                assert (s_axil_rresp == $past(s_axil_rresp));
                assert (s_axil_rdata == $past(s_axil_rdata));
            end
            assert (s_axil_bvalid == ($past(do_write) ||
                                      ($past(s_axil_bvalid) && !$past(s_axil_bready))));
            assert (s_axil_rvalid == ($past(ar_hs) ||
                                      ($past(s_axil_rvalid) && !$past(s_axil_rready))));
        end
    end

    // State invariants: at most one write half held, none while B pending.
    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held_q && w_held_q));
            if (bvalid_q) begin
                assert (!aw_held_q);
                assert (!w_held_q);
            end
            assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (b_hs);
            cover (r_hs);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
