// axi4_lite_regs_tb.v
// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven 1 time unit after each rising edge; outputs and
// handshakes are sampled before the next rising edge, so there is no race.
`default_nettype none

`define TB_CHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error("CHECK FAILED: %s (time %0t)", msg, $time); \
        end \
    end

module axi4_lite_regs_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg         aclk = 1'b0;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    always #5 aclk = ~aclk;

    // Verdict bookkeeping
    integer passed;
    integer failed;
    integer cyc;
    integer b_count;
    integer r_count;
    integer t_bc;
    integer t_rc;
    integer c0;
    reg [8*64-1:0] nonce;

    // Scoreboard / reference model
    reg [31:0] m0;
    reg [31:0] m1;
    reg [31:0] m2;
    reg [31:0] m3;
    reg        wr_aw_got;
    reg        wr_w_got;
    reg [3:0]  cap_addr;
    reg [31:0] cap_data;
    reg [3:0]  cap_strb;
    reg        b_pending;
    reg        r_pending;
    reg [1:0]  exp_bresp;
    reg [1:0]  exp_rresp;
    reg [31:0] exp_rdata;
    reg [1:0]  last_bresp;
    reg [1:0]  last_rresp;
    reg [31:0] last_rdata;

    function [31:0] merge;
        input [31:0] o;
        input [31:0] d;
        input [3:0]  s;
        begin
            merge = {s[3] ? d[31:24] : o[31:24],
                     s[2] ? d[23:16] : o[23:16],
                     s[1] ? d[15:8]  : o[15:8],
                     s[0] ? d[7:0]   : o[7:0]};
        end
    endfunction

    function [31:0] model_read;
        input [1:0] idx;
        begin
            case (idx)
                2'd0:    model_read = m0;
                2'd1:    model_read = m1;
                2'd2:    model_read = m2;
                default: model_read = m3;
            endcase
        end
    endfunction

    task model_write;
        input [3:0]  a;
        input [31:0] d;
        input [3:0]  s;
        begin
            case (a[3:2])
                2'd0:    m0 = merge(m0, d, s);
                2'd1:    m1 = merge(m1, d, s);
                2'd2:    m2 = merge(m2, d, s);
                default: m3 = merge(m3, d, s);
            endcase
        end
    endtask

    // One clock cycle: sample, edge, check, update the model, drop VALIDs
    // that completed their handshake.
    task tick;
        reg        p_rst;
        reg        p_awv;
        reg        p_awr;
        reg        p_wv;
        reg        p_wr;
        reg        p_arv;
        reg        p_arr;
        reg        p_bv;
        reg        p_br;
        reg        p_rv;
        reg        p_rr;
        reg [1:0]  p_bresp;
        reg [1:0]  p_rresp;
        reg [31:0] p_rdata;
        reg [3:0]  p_awaddr;
        reg [3:0]  p_araddr;
        reg [31:0] p_wdata;
        reg [3:0]  p_wstrb;
        reg        aw_fire;
        reg        w_fire;
        reg        ar_fire;
        reg        b_fire;
        reg        r_fire;
        begin
            #1;
            p_rst    = aresetn;
            p_awv    = s_axil_awvalid;
            p_awr    = s_axil_awready;
            p_wv     = s_axil_wvalid;
            p_wr     = s_axil_wready;
            p_arv    = s_axil_arvalid;
            p_arr    = s_axil_arready;
            p_bv     = s_axil_bvalid;
            p_br     = s_axil_bready;
            p_rv     = s_axil_rvalid;
            p_rr     = s_axil_rready;
            p_bresp  = s_axil_bresp;
            p_rresp  = s_axil_rresp;
            p_rdata  = s_axil_rdata;
            p_awaddr = s_axil_awaddr;
            p_araddr = s_axil_araddr;
            p_wdata  = s_axil_wdata;
            p_wstrb  = s_axil_wstrb;

            if (p_rst) begin
                `TB_CHECK(!(p_bv && (p_awr || p_wr)), "no AW or W accepted while a write response is pending")
                `TB_CHECK(!(p_rv && p_arr), "no AR accepted while read data is pending")
                `TB_CHECK(p_awr == (!wr_aw_got && !p_bv), "AWREADY equals not aw_held and not bvalid")
                `TB_CHECK(p_wr == (!wr_w_got && !p_bv), "WREADY equals not w_held and not bvalid")
                `TB_CHECK(p_arr == !p_rv, "ARREADY equals not rvalid")
            end

            @(posedge aclk);
            #1;
            cyc = cyc + 1;

            aw_fire = p_awv && p_awr;
            w_fire  = p_wv  && p_wr;
            ar_fire = p_arv && p_arr;
            b_fire  = p_bv  && p_br;
            r_fire  = p_rv  && p_rr;

            if (!p_rst) begin
                m0        = 32'h0000_0000;
                m1        = 32'h0000_0000;
                m2        = 32'h0000_0000;
                m3        = 32'h0000_0000;
                wr_aw_got = 1'b0;
                wr_w_got  = 1'b0;
                b_pending = 1'b0;
                r_pending = 1'b0;
                `TB_CHECK(!s_axil_bvalid && !s_axil_rvalid, "BVALID and RVALID low after a reset edge")
                `TB_CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after a reset edge")
            end else begin
                // B channel
                if (p_bv && !p_br) begin
                    `TB_CHECK(s_axil_bvalid && (s_axil_bresp == p_bresp), "BVALID and BRESP hold while BREADY is low")
                end
                if (b_fire) begin
                    `TB_CHECK(b_pending, "B handshake only for an outstanding write")
                    `TB_CHECK(p_bresp == exp_bresp, "BRESP matches the address policy")
                    last_bresp = p_bresp;
                    b_pending  = 1'b0;
                    b_count    = b_count + 1;
                    `TB_CHECK(s_axil_awready && s_axil_wready, "write channels ready the cycle after B is taken")
                end
                // R channel
                if (p_rv && !p_rr) begin
                    `TB_CHECK(s_axil_rvalid && (s_axil_rdata == p_rdata) && (s_axil_rresp == p_rresp), "RVALID RDATA RRESP hold while RREADY is low")
                end
                if (r_fire) begin
                    `TB_CHECK(r_pending, "R handshake only for an outstanding read")
                    `TB_CHECK(p_rdata == exp_rdata, "RDATA matches the reference model")
                    `TB_CHECK(p_rresp == exp_rresp, "RRESP matches the address policy")
                    last_rdata = p_rdata;
                    last_rresp = p_rresp;
                    r_pending  = 1'b0;
                    r_count    = r_count + 1;
                    `TB_CHECK(s_axil_arready, "read channel ready the cycle after R is taken")
                end
                // Read request: model state before this edge's write
                if (ar_fire) begin
                    r_pending = 1'b1;
                    if (p_araddr[1:0] == 2'b00) begin
                        exp_rdata = model_read(p_araddr[3:2]);
                        exp_rresp = OKAY;
                    end else begin
                        exp_rdata = 32'h0000_0000;
                        exp_rresp = SLVERR;
                    end
                    `TB_CHECK(s_axil_rvalid, "RVALID one cycle after AR accepted (bound 2)")
                    `TB_CHECK((s_axil_rdata == exp_rdata) && (s_axil_rresp == exp_rresp), "R payload correct when RVALID rises")
                end
                // Write pairing
                if (aw_fire) begin
                    cap_addr  = p_awaddr;
                    wr_aw_got = 1'b1;
                end
                if (w_fire) begin
                    cap_data = p_wdata;
                    cap_strb = p_wstrb;
                    wr_w_got = 1'b1;
                end
                if (wr_aw_got && wr_w_got) begin
                    if (cap_addr[1:0] == 2'b00) begin
                        exp_bresp = OKAY;
                        model_write(cap_addr, cap_data, cap_strb);
                    end else begin
                        exp_bresp = SLVERR;
                    end
                    wr_aw_got = 1'b0;
                    wr_w_got  = 1'b0;
                    b_pending = 1'b1;
                    `TB_CHECK(s_axil_bvalid, "BVALID one cycle after the write completes (bound 2)")
                end
                `TB_CHECK(s_axil_bvalid == b_pending, "BVALID high exactly when a write response is outstanding")
                `TB_CHECK(s_axil_rvalid == r_pending, "RVALID high exactly when a read response is outstanding")
                if (s_axil_bvalid) begin
                    `TB_CHECK((s_axil_bresp == OKAY) || (s_axil_bresp == SLVERR), "BRESP is OKAY or SLVERR")
                end
                if (s_axil_rvalid) begin
                    `TB_CHECK((s_axil_rresp == OKAY) || (s_axil_rresp == SLVERR), "RRESP is OKAY or SLVERR")
                end
                // Manager: drop VALID after its handshake
                if (aw_fire) s_axil_awvalid = 1'b0;
                if (w_fire)  s_axil_wvalid  = 1'b0;
                if (ar_fire) s_axil_arvalid = 1'b0;
            end
        end
    endtask

    task wait_quiet;
        integer n;
        begin
            n = 0;
            while ((s_axil_awvalid || s_axil_wvalid || s_axil_arvalid ||
                    b_pending || r_pending || wr_aw_got || wr_w_got) && (n < 64)) begin
                tick;
                n = n + 1;
            end
            `TB_CHECK(n < 64, "transactions complete without timeout")
        end
    endtask

    task send_aw;
        input [3:0] a;
        begin
            s_axil_awaddr  = a;
            s_axil_awvalid = 1'b1;
        end
    endtask

    task send_w;
        input [31:0] d;
        input [3:0]  s;
        begin
            s_axil_wdata  = d;
            s_axil_wstrb  = s;
            s_axil_wvalid = 1'b1;
        end
    endtask

    task send_ar;
        input [3:0] a;
        begin
            s_axil_araddr  = a;
            s_axil_arvalid = 1'b1;
        end
    endtask

    task write_both;
        input [3:0]  a;
        input [31:0] d;
        input [3:0]  s;
        input [1:0]  resp;
        integer bc;
        begin
            bc = b_count;
            send_aw(a);
            send_w(d, s);
            wait_quiet;
            `TB_CHECK(b_count == bc + 1, "exactly one B per write")
            `TB_CHECK(last_bresp == resp, "write response matches the address policy")
        end
    endtask

    task write_aw_first;
        input [3:0]  a;
        input [31:0] d;
        input [3:0]  s;
        input [1:0]  resp;
        input integer gap;
        integer bc;
        begin
            bc = b_count;
            send_aw(a);
            repeat (gap) tick;
            `TB_CHECK(wr_aw_got && !s_axil_bvalid && !s_axil_awvalid, "AW accepted alone and held without a response")
            send_w(d, s);
            wait_quiet;
            `TB_CHECK(b_count == bc + 1, "exactly one B per write (AW first)")
            `TB_CHECK(last_bresp == resp, "write response matches the address policy (AW first)")
        end
    endtask

    task write_w_first;
        input [3:0]  a;
        input [31:0] d;
        input [3:0]  s;
        input [1:0]  resp;
        input integer gap;
        integer bc;
        begin
            bc = b_count;
            send_w(d, s);
            repeat (gap) tick;
            `TB_CHECK(wr_w_got && !s_axil_bvalid && !s_axil_wvalid, "W accepted alone and held without a response")
            send_aw(a);
            wait_quiet;
            `TB_CHECK(b_count == bc + 1, "exactly one B per write (W first)")
            `TB_CHECK(last_bresp == resp, "write response matches the address policy (W first)")
        end
    endtask

    task expect_read;
        input [3:0]  a;
        input [31:0] d;
        input [1:0]  resp;
        integer rc;
        begin
            rc = r_count;
            send_ar(a);
            wait_quiet;
            `TB_CHECK(r_count == rc + 1, "exactly one R per read")
            `TB_CHECK(last_rdata == d, "read data matches the expected register value")
            `TB_CHECK(last_rresp == resp, "read response matches the address policy")
            if ((last_rdata != d) || (last_rresp != resp)) begin
                $display("  read 0x%h: got 0x%h/%b expected 0x%h/%b", a, last_rdata, last_rresp, d, resp);
            end
        end
    endtask

    initial begin
        passed     = 0;
        failed     = 0;
        cyc        = 0;
        b_count    = 0;
        r_count    = 0;
        t_bc       = 0;
        t_rc       = 0;
        c0         = 0;
        nonce      = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {(8*64){1'b0}};
        end

        m0         = 32'h0000_0000;
        m1         = 32'h0000_0000;
        m2         = 32'h0000_0000;
        m3         = 32'h0000_0000;
        wr_aw_got  = 1'b0;
        wr_w_got   = 1'b0;
        cap_addr   = 4'h0;
        cap_data   = 32'h0000_0000;
        cap_strb   = 4'h0;
        b_pending  = 1'b0;
        r_pending  = 1'b0;
        exp_bresp  = OKAY;
        exp_rresp  = OKAY;
        exp_rdata  = 32'h0000_0000;
        last_bresp = OKAY;
        last_rresp = OKAY;
        last_rdata = 32'h0000_0000;

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0000_0000;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b1;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b1;

        // ---------------- Reset ----------------
        repeat (3) tick;
        aresetn = 1'b1;
        tick;
        `TB_CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after reset")
        `TB_CHECK(!s_axil_bvalid && !s_axil_rvalid, "no response after reset")

        // ---------------- T1: reset values ----------------
        expect_read(4'h0, 32'h0000_0000, OKAY);
        expect_read(4'h4, 32'h0000_0000, OKAY);
        expect_read(4'h8, 32'h0000_0000, OKAY);
        expect_read(4'hC, 32'h0000_0000, OKAY);

        // ---------------- T2: write then read every register ----------------
        write_both(4'h0, 32'h0123_4567, 4'hF, OKAY);
        write_both(4'h4, 32'h89AB_CDEF, 4'hF, OKAY);
        write_both(4'h8, 32'hFEDC_BA98, 4'hF, OKAY);
        write_both(4'hC, 32'h7654_3210, 4'hF, OKAY);
        expect_read(4'h0, 32'h0123_4567, OKAY);
        expect_read(4'h4, 32'h89AB_CDEF, OKAY);
        expect_read(4'h8, 32'hFEDC_BA98, OKAY);
        expect_read(4'hC, 32'h7654_3210, OKAY);

        // ---------------- T3: AW/W ordering ----------------
        write_aw_first(4'h4, 32'hAAAA_0001, 4'hF, OKAY, 3);
        expect_read(4'h4, 32'hAAAA_0001, OKAY);
        write_w_first(4'h8, 32'hBBBB_0002, 4'hF, OKAY, 3);
        expect_read(4'h8, 32'hBBBB_0002, OKAY);
        write_aw_first(4'hC, 32'hCCCC_0003, 4'hF, OKAY, 1);
        expect_read(4'hC, 32'hCCCC_0003, OKAY);
        write_w_first(4'h0, 32'hDDDD_0004, 4'hF, OKAY, 1);
        expect_read(4'h0, 32'hDDDD_0004, OKAY);
        write_both(4'hC, 32'hEEEE_0005, 4'hF, OKAY);
        expect_read(4'hC, 32'hEEEE_0005, OKAY);

        // ---------------- T4: WSTRB ----------------
        write_both(4'h0, 32'h1234_5678, 4'hF, OKAY);
        write_both(4'h0, 32'hFFFF_FFAA, 4'b0001, OKAY);
        expect_read(4'h0, 32'h1234_56AA, OKAY);
        write_both(4'h0, 32'hBBCC_DDEE, 4'b1010, OKAY);
        expect_read(4'h0, 32'hBB34_DDAA, OKAY);
        write_both(4'h0, 32'hFFFF_FFFF, 4'b0000, OKAY);
        expect_read(4'h0, 32'hBB34_DDAA, OKAY);
        write_both(4'h4, 32'h0000_0000, 4'hF, OKAY);
        write_w_first(4'h4, 32'h5566_7788, 4'b0110, OKAY, 2);
        expect_read(4'h4, 32'h0066_7700, OKAY);
        write_aw_first(4'h8, 32'h9999_9999, 4'b1100, OKAY, 2);
        expect_read(4'h8, 32'h9999_0002, OKAY);

        // ---------------- T5: SLVERR policy ----------------
        write_both(4'h5, 32'hFFFF_FFFF, 4'hF, SLVERR);
        expect_read(4'h4, 32'h0066_7700, OKAY);
        write_aw_first(4'hE, 32'hFFFF_FFFF, 4'hF, SLVERR, 2);
        expect_read(4'hC, 32'hEEEE_0005, OKAY);
        write_w_first(4'h3, 32'hFFFF_FFFF, 4'hF, SLVERR, 2);
        expect_read(4'h0, 32'hBB34_DDAA, OKAY);
        expect_read(4'h5, 32'h0000_0000, SLVERR);
        expect_read(4'hE, 32'h0000_0000, SLVERR);
        expect_read(4'h1, 32'h0000_0000, SLVERR);
        expect_read(4'hA, 32'h0000_0000, SLVERR);

        // ---------------- T6: B backpressure ----------------
        t_bc = b_count;
        s_axil_bready = 1'b0;
        send_aw(4'h8);
        send_w(32'hDEAD_BEEF, 4'hF);
        tick;
        `TB_CHECK(s_axil_bvalid && (s_axil_bresp == OKAY), "write answered while BREADY is low")
        send_aw(4'hC);
        send_w(32'hFEED_F00D, 4'hF);
        repeat (5) tick;
        `TB_CHECK(s_axil_awvalid && s_axil_wvalid && !wr_aw_got && !wr_w_got, "no new write accepted while B is stalled")
        `TB_CHECK(b_count == t_bc, "no B taken while BREADY is low")
        s_axil_bready = 1'b1;
        wait_quiet;
        `TB_CHECK(b_count == t_bc + 2, "both writes answered after BREADY rises")
        `TB_CHECK(last_bresp == OKAY, "second write answered OKAY")
        expect_read(4'h8, 32'hDEAD_BEEF, OKAY);
        expect_read(4'hC, 32'hFEED_F00D, OKAY);

        // ---------------- T7: R backpressure ----------------
        t_rc = r_count;
        s_axil_rready = 1'b0;
        send_ar(4'h8);
        tick;
        `TB_CHECK(s_axil_rvalid && (s_axil_rdata == 32'hDEAD_BEEF) && (s_axil_rresp == OKAY), "read answered while RREADY is low")
        send_aw(4'h8);
        send_w(32'h1111_2222, 4'hF);
        tick;
        tick;
        `TB_CHECK(!s_axil_bvalid && !b_pending, "write completes while R is stalled")
        send_ar(4'hC);
        repeat (4) tick;
        `TB_CHECK(s_axil_rvalid && (s_axil_rdata == 32'hDEAD_BEEF), "RDATA holds while stalled after the register changed")
        `TB_CHECK(s_axil_arvalid && (r_count == t_rc), "no new read accepted while R is stalled")
        s_axil_rready = 1'b1;
        wait_quiet;
        `TB_CHECK(r_count == t_rc + 2, "both reads answered after RREADY rises")
        `TB_CHECK((last_rdata == 32'hFEED_F00D) && (last_rresp == OKAY), "second read returns REG3")
        expect_read(4'h8, 32'h1111_2222, OKAY);

        // ---------------- T8: back-to-back throughput ----------------
        c0 = cyc;
        write_both(4'h0, 32'h0000_0001, 4'hF, OKAY);
        write_both(4'h4, 32'h0000_0002, 4'hF, OKAY);
        write_both(4'h8, 32'h0000_0003, 4'hF, OKAY);
        write_both(4'hC, 32'h0000_0004, 4'hF, OKAY);
        `TB_CHECK(cyc - c0 == 8, "four back-to-back writes take 8 cycles")
        c0 = cyc;
        expect_read(4'h0, 32'h0000_0001, OKAY);
        expect_read(4'h4, 32'h0000_0002, OKAY);
        expect_read(4'h8, 32'h0000_0003, OKAY);
        expect_read(4'hC, 32'h0000_0004, OKAY);
        `TB_CHECK(cyc - c0 == 8, "four back-to-back reads take 8 cycles")

        // ---------------- T9: concurrent read and write ----------------
        send_aw(4'h0);
        send_w(32'hCAFE_0000, 4'hF);
        send_ar(4'h4);
        wait_quiet;
        `TB_CHECK((last_rdata == 32'h0000_0002) && (last_bresp == OKAY), "independent read and write in the same cycle")
        expect_read(4'h0, 32'hCAFE_0000, OKAY);
        send_aw(4'h8);
        send_w(32'h5A5A_5A5A, 4'hF);
        send_ar(4'h8);
        wait_quiet;
        `TB_CHECK(last_rdata == 32'h0000_0003, "same-cycle read of a register being written returns the old value")
        expect_read(4'h8, 32'h5A5A_5A5A, OKAY);

        // ---------------- T10: reset during traffic ----------------
        send_aw(4'h0);
        tick;
        `TB_CHECK(wr_aw_got && !s_axil_bvalid, "AW held before reset")
        aresetn = 1'b0;
        tick;
        tick;
        aresetn = 1'b1;
        send_w(32'h7777_7777, 4'hF);
        repeat (3) tick;
        `TB_CHECK(!s_axil_bvalid && !b_pending && wr_w_got, "half-accepted write discarded by reset")
        send_aw(4'h4);
        wait_quiet;
        expect_read(4'h4, 32'h7777_7777, OKAY);
        expect_read(4'h0, 32'h0000_0000, OKAY);
        expect_read(4'h8, 32'h0000_0000, OKAY);
        expect_read(4'hC, 32'h0000_0000, OKAY);

        s_axil_bready = 1'b0;
        s_axil_rready = 1'b0;
        send_aw(4'h8);
        send_w(32'h1212_1212, 4'hF);
        send_ar(4'h4);
        tick;
        tick;
        `TB_CHECK(s_axil_bvalid && s_axil_rvalid, "B and R pending before reset")
        aresetn = 1'b0;
        tick;
        `TB_CHECK(!s_axil_bvalid && !s_axil_rvalid, "pending responses cleared by reset")
        aresetn = 1'b1;
        s_axil_bready = 1'b1;
        s_axil_rready = 1'b1;
        tick;
        expect_read(4'h8, 32'h0000_0000, OKAY);
        expect_read(4'h4, 32'h0000_0000, OKAY);
        write_both(4'hC, 32'hA5A5_5A5A, 4'hF, OKAY);
        expect_read(4'hC, 32'hA5A5_5A5A, OKAY);

        // ---------------- Verdict ----------------
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
